    return {"sha": f"s{i}", "date": f"2026-10-0{i + 1}", "subject": subject, "pr": None, "author": "a", "term": "x",
            "area": area, "area_src": src, "covered": False, "judge": "text", "closest_page": "", "files": files}


REL = {"name": "v1", "previous": "v0", "date": "2026-10-05", "commits": []}


